import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_dim1_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<8>;

    // k = blockIdx.x * blockDim.x + threadIdx.x  (column index in dim2)
    mov.u32 %r0, %ctaid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %tid.x;
    mad.lo.u32 %r3, %r0, %r1, %r2;

    ld.param.u32 %r4, [dim2];
    setp.ge.u32 %p0, %r3, %r4;
    @%p0 bra $DONE;

    // b = blockIdx.y (batch index)
    mov.u32 %r5, %ctaid.y;
    ld.param.u32 %r6, [dim1];

    // base element index = (b * dim1) * dim2 + k  (64-bit)
    cvt.u64.u32 %rd1, %r5;
    cvt.u64.u32 %rd2, %r6;
    mul.lo.u64 %rd3, %rd1, %rd2;
    cvt.u64.u32 %rd4, %r4;
    mul.lo.u64 %rd5, %rd3, %rd4;
    cvt.u64.u32 %rd6, %r3;
    add.u64 %rd7, %rd5, %rd6;

    // address of x[b, 0, k]
    ld.param.u64 %rd8, [in_ptr];
    shl.b64 %rd9, %rd7, 2;
    add.u64 %rd10, %rd8, %rd9;

    // row stride in bytes = dim2 * 4
    shl.b64 %rd11, %rd4, 2;

    // accumulator = -inf
    mov.f32 %f0, 0fFF800000;
    mov.u32 %r7, 0;

$LOOP:
    setp.ge.u32 %p1, %r7, %r6;
    @%p1 bra $STORE;
    ld.global.f32 %f1, [%rd10];
    max.NaN.f32 %f0, %f0, %f1;
    add.u64 %rd10, %rd10, %rd11;
    add.u32 %r7, %r7, 1;
    bra $LOOP;

$STORE:
    // out[b, k] address
    ld.param.u64 %rd12, [out_ptr];
    mul.lo.u64 %rd13, %rd1, %rd4;
    add.u64 %rd13, %rd13, %rd6;
    shl.b64 %rd13, %rd13, 2;
    add.u64 %rd14, %rd12, %rd13;
    st.global.f32 [%rd14], %f0;

$DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_dim1_kernel")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, dim1, dim2 = x.shape[0], x.shape[1], x.shape[2]
        out = torch.empty((batch_size, dim2), device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        threads = 256
        grid_x = (dim2 + threads - 1) // threads
        module.launch(
            "max_reduce_dim1_kernel",
            grid=(grid_x, batch_size, 1),
            block=(threads, 1, 1),
            arguments=[x, out, i32(dim1), i32(dim2)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

